import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
#include <c10/util/Optional.h>

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <climits>

constexpr int TILE_H = 16;
constexpr int TILE_W = 16;
constexpr int OC_TILE = 16;
constexpr int BLOCK_THREADS = TILE_H * TILE_W;

__global__ void conv2d_tiled_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int OC, int KH, int KW,
    int OH, int OW,
    int sh, int sw, int ph, int pw, int dh, int dw,
    int halo_h, int halo_w)
{
    extern __shared__ float smem[];
    float* s_in = smem;
    float* s_w = s_in + halo_h * halo_w;

    const int oc_groups = (OC + OC_TILE - 1) / OC_TILE;
    const int n = blockIdx.z / oc_groups;
    const int oc0 = (blockIdx.z - n * oc_groups) * OC_TILE;
    const int oh0 = blockIdx.y * TILE_H;
    const int ow0 = blockIdx.x * TILE_W;

    const int tid = threadIdx.x;
    const int tx = tid % TILE_W;
    const int ty = tid / TILE_W;
    const int oh = oh0 + ty;
    const int ow = ow0 + tx;
    const bool out_valid = (oh < OH) && (ow < OW);

    float acc[OC_TILE];
    #pragma unroll
    for (int i = 0; i < OC_TILE; ++i) acc[i] = 0.0f;

    const int in_tile_elems = halo_h * halo_w;
    const int w_tile_elems = OC_TILE * KH * KW;
    const int in_base_h = oh0 * sh - ph;
    const int in_base_w = ow0 * sw - pw;

    for (int c = 0; c < C; ++c) {
        for (int idx = tid; idx < in_tile_elems; idx += BLOCK_THREADS) {
            const int r = idx / halo_w;
            const int col = idx - r * halo_w;
            const int ih = in_base_h + r;
            const int iw = in_base_w + col;
            float v = 0.0f;
            if (ih >= 0 && ih < H && iw >= 0 && iw < W) {
                v = input[((n * C + c) * H + ih) * W + iw];
            }
            s_in[idx] = v;
        }

        for (int idx = tid; idx < w_tile_elems; idx += BLOCK_THREADS) {
            const int oc_local = idx / (KH * KW);
            const int rem = idx - oc_local * (KH * KW);
            const int kh = rem / KW;
            const int kw = rem - kh * KW;
            const int oc = oc0 + oc_local;
            float v = 0.0f;
            if (oc < OC) {
                v = weight[((oc * C + c) * KH + kh) * KW + kw];
            }
            s_w[idx] = v;
        }

        __syncthreads();

        if (out_valid) {
            #pragma unroll
            for (int ol = 0; ol < OC_TILE; ++ol) {
                const float* wp = s_w + ol * KH * KW;
                float sum = acc[ol];
                for (int kh = 0; kh < KH; ++kh) {
                    const int ir = ty * sh + kh * dh;
                    const int row = ir * halo_w;
                    for (int kw = 0; kw < KW; ++kw) {
                        const int ic = tx * sw + kw * dw;
                        sum += s_in[row + ic] * wp[kh * KW + kw];
                    }
                }
                acc[ol] = sum;
            }
        }

        __syncthreads();
    }

    if (out_valid) {
        #pragma unroll
        for (int ol = 0; ol < OC_TILE; ++ol) {
            const int oc = oc0 + ol;
            if (oc < OC) {
                float v = acc[ol];
                if (bias != nullptr) v += bias[oc];
                output[((n * OC + oc) * OH + oh) * OW + ow] = v;
            }
        }
    }
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    const c10::optional<torch::Tensor>& bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t pad_h,
    int64_t pad_w,
    int64_t dil_h,
    int64_t dil_w)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be OIHW");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "weight must be contiguous");

    const int N = (int)input.size(0);
    const int C = (int)input.size(1);
    const int H = (int)input.size(2);
    const int W = (int)input.size(3);
    const int OC = (int)weight.size(0);
    const int KH = (int)weight.size(2);
    const int KW = (int)weight.size(3);
    TORCH_CHECK(weight.size(1) == C, "weight in_channels mismatch");

    const int sh = (int)stride_h;
    const int sw = (int)stride_w;
    const int ph = (int)pad_h;
    const int pw = (int)pad_w;
    const int dh = (int)dil_h;
    const int dw = (int)dil_w;

    const int eff_kh = (KH - 1) * dh + 1;
    const int eff_kw = (KW - 1) * dw + 1;
    const int OH = (H + 2 * ph - eff_kh) / sh + 1;
    const int OW = (W + 2 * pw - eff_kw) / sw + 1;
    TORCH_CHECK(OH > 0 && OW > 0, "invalid output size");
    auto output = torch::empty({N, OC, OH, OW}, input.options());
    TORCH_CHECK(input.numel() < INT32_MAX && output.numel() < INT32_MAX, "tensor too large");

    const float* bias_ptr = nullptr;
    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be CUDA");
        TORCH_CHECK(bias->scalar_type() == torch::kFloat32, "bias must be float32");
        TORCH_CHECK(bias->is_contiguous(), "bias must be contiguous");
        TORCH_CHECK(bias->numel() == OC, "bias size mismatch");
        bias_ptr = bias->data_ptr<float>();
    }

    const int halo_h = (TILE_H - 1) * sh + eff_kh;
    const int halo_w = (TILE_W - 1) * sw + eff_kw;
    const size_t shmem_bytes =
        ((size_t)halo_h * (size_t)halo_w + (size_t)OC_TILE * (size_t)KH * (size_t)KW) * sizeof(float);
    TORCH_CHECK(shmem_bytes <= 48 * 1024, "shared memory requirement too large");

    dim3 block(BLOCK_THREADS);
    dim3 grid((OW + TILE_W - 1) / TILE_W,
              (OH + TILE_H - 1) / TILE_H,
              N * ((OC + OC_TILE - 1) / OC_TILE));

    auto stream = at::cuda::getCurrentCUDAStream();
    conv2d_tiled_kernel<<<grid, block, shmem_bytes, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C, H, W,
        OC, KH, KW,
        OH, OW,
        sh, sw, ph, pw, dh, dw,
        halo_h, halo_w);
    C10_CUDA_KERNEL_LAUNCH_CHECK();

    return output;
}
"""

_conv_mod = load_inline(
    name="custom_conv2d_tiled",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: int = 1,
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = tuple(kernel_size)
        self.stride = int(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)

        kh, kw = self.kernel_size
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size[0] * self.kernel_size[1]
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv_mod.conv2d_forward(
            x,
            self.weight,
            self.bias,
            self.stride,
            self.stride,
            self.padding[0],
            self.padding[1],
            self.dilation[0],
            self.dilation[1],
        )

